"""Meridian CRM 4.2 batch-job error-handling runner migration."""

from typing import Any, Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], Any]) -> list[dict]:
    """Run scheduled jobs sequentially, preserving legacy ON_ERROR semantics.

    The executor is invoked once for normal jobs and CONTINUE/ABORT failures.
    RETRY jobs may receive the configured number of additional immediate attempts.
    """
    run_log: list[dict] = []

    for job in jobs:
        on_error = job["on_error"]
        policy = on_error["policy"]
        retries = on_error["retries"] if policy == "RETRY" else 0
        attempts = 0

        while attempts <= retries:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "RETRY" and attempts <= retries:
                    continue

                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

    return run_log
